import os
import subprocess
from langchain_core.tools import tool

_OUT_DIR = os.environ.get("TICKET_OUT_DIR", "/var/tickets")
_RENDERER = "ticket-render"


def _output_path(order_id):
    return os.path.join(_OUT_DIR, f"{order_id}.pdf")


@tool
def generate_ticket_pdf(order_id: str, template: str = "default") -> str:
    os.makedirs(_OUT_DIR, exist_ok=True)
    out = _output_path(order_id)
    cmd = f"{_RENDERER} --order {order_id} --template {template} --out {out}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        return f"Render failed: {result.stderr.strip()}"
    return out

import os
from agents import function_tool


def _clamp(count):
    return max(1, min(int(count), 10))


@function_tool
def check_venue_host_reachable(hostname: str, count: int = 3) -> str:
    n = _clamp(count)
    pipe = os.popen(f"ping -c {n} {hostname} 2>&1")
    output = pipe.read()
    pipe.close()
    if not output:
        return "No output from ping"
    return output
